import { readFileSync } from 'node:fs';
import path from 'node:path';
import type { Recording } from '../../lib/ai/types';
import { setRecordingSink } from '../../lib/ai/replay';
import type { TenantId } from '../../lib/contracts';
import { evaluateUploadedDocuments } from '../../lib/agents/prequal';
import { toUploadedDocument, type UploadedDocument } from '../../lib/agents/uploads';
import { TENANT_IDS } from '../../lib/agents/tenants';
import { RECORDINGS } from '../recordings';
import { writeRecordings } from './recordings-io';

/** Sample files generated by scripts/generate-sample-docs.ts (committed). */
const SAMPLES_DIR = path.resolve(process.cwd(), 'seed', 'docs', 'samples');
export type SampleFormat = 'png' | 'pdf';
const STEMS = ['dni', 'payslip', 'income-certificate', 'surety-insurance'] as const;

function load(dir: string, name: string, format: SampleFormat): UploadedDocument {
  const file = `${name}.${format}`;
  return toUploadedDocument(file, new Uint8Array(readFileSync(path.join(SAMPLES_DIR, dir, file))));
}

/** The four documents of a demo tenant, as uploaded files. */
export function tenantUploads(tenantId: TenantId, format: SampleFormat): UploadedDocument[] {
  return STEMS.map((stem) => load(tenantId, `${tenantId}-${stem}`, format));
}

/** Ana's documents with her payslip swapped for the poisoned one (prompt injection inside the file). */
export function poisonedUploads(format: SampleFormat): UploadedDocument[] {
  return STEMS.map((stem) =>
    stem === 'payslip' ? load('poisoned', 'ana-payslip-poisoned', format) : load('ana', `ana-${stem}`, format),
  );
}

export const POISONED_INCOME = 99999;

/** Agent id fragment that marks recordings produced by the upload agents. */
export const UPLOAD_AGENT_MARK = '.upload@';

export function isUploadRecording(rec: Recording): boolean {
  return rec.agent.includes(UPLOAD_AGENT_MARK);
}

/**
 * Records every upload scenario live (PNG and PDF, three tenants + poisoned) and merges the result into
 * evals/recordings, keeping every other recording. Two model calls per bundle (prequal + crosscheck).
 */
export async function recordUploadScenarios(): Promise<string[]> {
  process.env.RECORD = '1';
  process.env.REPLAY = '0';
  const collected: Recording[] = [];
  setRecordingSink((rec) => {
    collected.push(rec);
  });
  try {
    for (const format of ['png', 'pdf'] as const) {
      for (const tenantId of TENANT_IDS) {
        const d = await evaluateUploadedDocuments(tenantId, tenantUploads(tenantId, format));
        console.log(`  ${tenantId}.${format}: ${d.status} (decided by ${d.decidedBy})`);
      }
      const p = await evaluateUploadedDocuments('ana', poisonedUploads(format));
      console.log(`  poisoned.${format}: ${p.status} income=${p.prequal.extracted.monthlyIncomeUsdc}`);
    }
  } finally {
    setRecordingSink(null);
  }
  const keep = RECORDINGS.filter((r) => !collected.some((c) => c.key === r.key));
  return writeRecordings([...keep, ...collected]);
}
